-- ===================================================== Procedures ===================================================== 
 
create or replace package PKG_METRO_OCORRENCIA as
    procedure CADASTRAR_OCORRENCIA(
        p_tipo_problema in varchar2,
        p_mensagem in clob,
        p_fk_id_funcionario in number,
        p_fk_id_estacao in number
    );
 
    procedure FINALIZAR_OCORRENCIA(
        p_id_ocorrencia in number
    );
end PKG_METRO_OCORRENCIA;
/
 
create or replace package body PKG_METRO_OCORRENCIA as
 
    procedure CADASTRAR_OCORRENCIA(
        p_tipo_problema in varchar2,
        p_mensagem in clob,
        p_fk_id_funcionario in number,
        p_fk_id_estacao in number
    ) is
        v_ativa T_METRO_ESTACAO.ATIVA%TYPE;
    begin
        select ativa into v_ativa from T_METRO_ESTACAO where id_estacao = p_fk_id_estacao;
 
        insert into T_METRO_OCORRENCIA (
            tipo_problema,
            mensagem,
            status,
            dt_inicio,
            fk_id_funcionario,
            fk_id_estacao
        ) values (
            p_tipo_problema,
            p_mensagem,
            'S',
            systimestamp,
            p_fk_id_funcionario,
            p_fk_id_estacao
        );
 
        if v_ativa = 'S' then
            update T_METRO_ESTACAO set ativa = 'N' where id_estacao = p_fk_id_estacao;
        end if;
 
    exception
        when no_data_found then
            dbms_output.put_line('Estação não encontrada: ' || p_fk_id_estacao);
        when value_error then
            dbms_output.put_line('Erro de valor inválido ao cadastrar ocorrência: ' || sqlerrm);
        when too_many_rows then
            dbms_output.put_line('Erro: mais de uma estação encontrada: ' || p_fk_id_estacao);
        when others then
            dbms_output.put_line('Erro ao cadastrar ocorrência: ' || sqlerrm);
    end CADASTRAR_OCORRENCIA;
 
    procedure FINALIZAR_OCORRENCIA(
        p_id_ocorrencia in number
    ) is
        v_status     T_METRO_OCORRENCIA.STATUS%TYPE;
        v_id_estacao T_METRO_OCORRENCIA.FK_ID_ESTACAO%TYPE;
        v_abertas    number;
    begin
        select status, fk_id_estacao
        into v_status, v_id_estacao
        from T_METRO_OCORRENCIA
        where id_ocorrencia = p_id_ocorrencia;

        if v_status = 'N' then
            dbms_output.put_line('Ocorrência ' || p_id_ocorrencia || ' já está finalizada.');
            return;
        end if;

        update T_METRO_OCORRENCIA set status = 'N', dt_fim = systimestamp where id_ocorrencia = p_id_ocorrencia;

        select count(*) into v_abertas from T_METRO_OCORRENCIA where fk_id_estacao = v_id_estacao and status = 'S';

        if v_abertas = 0 then
            update T_METRO_ESTACAO set ativa = 'S' where id_estacao = v_id_estacao;
        else
            dbms_output.put_line('Estação ' || v_id_estacao || ' continua inativa: ' || 
            v_abertas || ' ocorrência(s) ainda aberta(s).');
        end if;

    exception
        when no_data_found then
            dbms_output.put_line('Ocorrência não encontrada: ' || p_id_ocorrencia);
        when value_error then
            dbms_output.put_line('Erro de valor inválido ao finalizar ocorrência: ' || sqlerrm);
        when too_many_rows then
            dbms_output.put_line('Erro: mais de uma ocorrência encontrada: ' || p_id_ocorrencia);
        when others then
            dbms_output.put_line('Erro ao finalizar ocorrência: ' || sqlerrm);
    end FINALIZAR_OCORRENCIA;
 
end PKG_METRO_OCORRENCIA;
/
 
-- ===================================================== Funções ===================================================== 
 
create or replace package PKG_METRO_CONSULTA as
    function QTD_OCORRENCIA return number;
    function PORCENTUAL_ATIVA return number;
 
end PKG_METRO_CONSULTA;
/
 
create or replace package body PKG_METRO_CONSULTA as
 
    function QTD_OCORRENCIA return number is
        v_qtd number;
    begin
        select count(*) into v_qtd from T_METRO_OCORRENCIA;
        return v_qtd;
 
    exception
        when others then
            dbms_output.put_line('Erro ao consultar quantidade de ocorrências: ' || sqlerrm);
            return null;
 
    end QTD_OCORRENCIA;
 
    function PORCENTUAL_ATIVA return number is
        v_total number;
        v_ativas number;
    begin
        select count(*) into v_total from T_METRO_ESTACAO;
        select count(*) into v_ativas from T_METRO_ESTACAO where ativa = 'S';
        if v_total = 0 then
            return 0;
        else
            return round((v_ativas / v_total) * 100, 2);
        end if;
 
    exception
        when others then
            dbms_output.put_line('Erro ao consultar percentual de estações ativas: ' || sqlerrm);
            return null;
 
    end PORCENTUAL_ATIVA;
 
end PKG_METRO_CONSULTA;
/

