-- ===================================================== T_METRO_ESTACAO =====================================================
 
create or replace trigger t_auditoria_estacao
after insert or update or delete on t_metro_estacao
for each row
declare
    v_operacao       varchar2(10);
    v_valor_anterior varchar2(4000);
    v_valor_novo     varchar2(4000);
begin
    if inserting then
        v_operacao := 'insert';
 
        v_valor_novo := 'id: ' || :new.id_estacao || ', nome: ' || :new.nm_estacao ||
                        ', ordem: ' || :new.ordem || ', linha: ' || :new.linha ||
                        ', ativa: ' || :new.ativa || ', sentido: ' || :new.sentido;
 
        insert into t_metro_audit_estacao
            (nm_estacao, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:new.nm_estacao, v_operacao, systimestamp, null, v_valor_novo);
 
    elsif updating then
        v_operacao := 'update';
 
        v_valor_anterior := 'id: ' || :old.id_estacao || ', nome: ' || :old.nm_estacao ||
                            ', ordem: ' || :old.ordem || ', linha: ' || :old.linha ||
                            ', ativa: ' || :old.ativa || ', sentido: ' || :old.sentido;
 
        v_valor_novo := 'id: ' || :new.id_estacao || ', nome: ' || :new.nm_estacao ||
                        ', ordem: ' || :new.ordem || ', linha: ' || :new.linha ||
                        ', ativa: ' || :new.ativa || ', sentido: ' || :new.sentido;
 
        insert into t_metro_audit_estacao
            (nm_estacao, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:new.nm_estacao, v_operacao, systimestamp, v_valor_anterior, v_valor_novo);
 
    elsif deleting then
        v_operacao := 'delete';
 
        v_valor_anterior := 'id: ' || :old.id_estacao || ', nome: ' || :old.nm_estacao ||
                            ', ordem: ' || :old.ordem || ', linha: ' || :old.linha ||
                            ', ativa: ' || :old.ativa || ', sentido: ' || :old.sentido;
 
        insert into t_metro_audit_estacao
            (nm_estacao, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:old.nm_estacao, v_operacao, systimestamp, v_valor_anterior, null);
    end if;
 
exception
    when others then
        dbms_output.put_line('ocorreu um erro inesperado na trigger t_auditoria_estacao: ' || SQLERRM);
end;
/
 

