            (nm_usuario, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:old.nm_funcionario, v_operacao, systimestamp, v_valor_anterior, null);
    end if;
 
exception
    when others then
        dbms_output.put_line('ocorreu um erro inesperado na trigger t_auditoria_funcionario: ' || SQLERRM);
end;
/
 
-- ===================================================== T_METRO_OCORRENCIA =====================================================
 
create or replace trigger t_auditoria_ocorrencia
after insert or update or delete on t_metro_ocorrencia
for each row
declare
    v_operacao       varchar2(10);
    v_valor_anterior varchar2(4000);
    v_valor_novo     varchar2(4000);
begin
    if inserting then
        v_operacao := 'insert';
 
        v_valor_novo := 'id: ' || :new.id_ocorrencia || ', tipo: ' || :new.tipo_problema ||
                        ', mensagem: ' || dbms_lob.substr(:new.mensagem, 1000, 1) ||
                        ', status: ' || :new.status ||
                        ', inicio: ' || to_char(:new.dt_inicio, 'DD/MM/YYYY HH24:MI:SS') ||
                        ', fim: ' || to_char(:new.dt_fim, 'DD/MM/YYYY HH24:MI:SS') ||
