                            ', funcionario: ' || :old.fk_id_funcionario ||
                            ', estacao: ' || :old.fk_id_estacao;
 
        v_valor_novo := 'id: ' || :new.id_ocorrencia || ', tipo: ' || :new.tipo_problema ||
                        ', mensagem: ' || dbms_lob.substr(:new.mensagem, 1000, 1) ||
                        ', status: ' || :new.status ||
                        ', inicio: ' || to_char(:new.dt_inicio, 'DD/MM/YYYY HH24:MI:SS') ||
                        ', fim: ' || to_char(:new.dt_fim, 'DD/MM/YYYY HH24:MI:SS') ||
                        ', funcionario: ' || :new.fk_id_funcionario ||
                        ', estacao: ' || :new.fk_id_estacao;
 
        insert into t_metro_audit_ocorrencia
            (tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (v_operacao, systimestamp, v_valor_anterior, v_valor_novo);
 
    elsif deleting then
        v_operacao := 'delete';
 
        v_valor_anterior := 'id: ' || :old.id_ocorrencia || ', tipo: ' || :old.tipo_problema ||
                            ', mensagem: ' || dbms_lob.substr(:old.mensagem, 1000, 1) ||
                            ', status: ' || :old.status ||
                            ', inicio: ' || to_char(:old.dt_inicio, 'DD/MM/YYYY HH24:MI:SS') ||
                            ', fim: ' || to_char(:old.dt_fim, 'DD/MM/YYYY HH24:MI:SS') ||
                            ', funcionario: ' || :old.fk_id_funcionario ||
                            ', estacao: ' || :old.fk_id_estacao;
 
        insert into t_metro_audit_ocorrencia
            (tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (v_operacao, systimestamp, v_valor_anterior, null);
    end if;
 
exception
