-- ===================================================== T_METRO_USUARIO =====================================================
 
create or replace trigger t_auditoria_metro_usuario
after insert or update or delete on t_metro_usuario
for each row
declare
    v_operacao       varchar2(10);
    v_valor_anterior varchar2(4000);
    v_valor_novo     varchar2(4000);
begin
    if inserting then
        v_operacao := 'insert';
 
        v_valor_novo := 'id: ' || :new.id_usuario || ', nome: ' || :new.nm_usuario ||
                        ', email: ' || :new.email;
 
        insert into t_metro_audit_usuario
            (nm_usuario, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:new.nm_usuario, v_operacao, systimestamp, null, v_valor_novo);
 
    elsif updating then
        v_operacao := 'update';
 
        v_valor_anterior := 'id: ' || :old.id_usuario || ', nome: ' || :old.nm_usuario ||
                            ', email: ' || :old.email;
 
        v_valor_novo := 'id: ' || :new.id_usuario || ', nome: ' || :new.nm_usuario ||
                        ', email: ' || :new.email;
 
        insert into t_metro_audit_usuario
            (nm_usuario, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:new.nm_usuario, v_operacao, systimestamp, v_valor_anterior, v_valor_novo);
 
    elsif deleting then
        v_operacao := 'delete';
 
        v_valor_anterior := 'id: ' || :old.id_usuario || ', nome: ' || :old.nm_usuario ||
                            ', email: ' || :old.email;
 
        insert into t_metro_audit_usuario
            (nm_usuario, tipo_operacao, dt_hr_operacao, valor_anterior, valor_novo)
        values
            (:old.nm_usuario, v_operacao, systimestamp, v_valor_anterior, null);
    end if;
 
exception
    when others then
        dbms_output.put_line('ocorreu um erro inesperado na trigger t_auditoria_metro_usuario: ' || SQLERRM);
end;
/



